	public bool isLQA => Singleton<GameDataController>.Instance.isLQA;

	public static bool binFormatEnabled => GameDataController.binFormatEnabled;

	[BlackList]
	public Achievement GetAchievement(int key)
	{
		if (!AchievementData.TryGetValue(key, out var value))
		{
			return null;
		}
		return value;
	}

	[BlackList]
	public void UnloadAchievement()
	{
		Achievement_Map = null;
	}

	private void AddAchievementBin(int key, byte[] data)
	{
		Achievement achievement = Achievement.Parser.ParseFrom(data);
		if (achievement != null)
		{
			Achievement_Map.Add(key, achievement);
		}
	}

	private void LoadAchievementBin()
	{
		if (Achievement_Map == null)
		{
			Achievement_Map = new Dictionary<int, Achievement>();
		}
		Achievement_Map.Clear();
		LoadCommonBinData("bin/Achievement.bytes", AddAchievementBin, null, null, null);
		if (!isLQA)
		{
			HandleAchievementLanguage();
		}
	}

	private void LoadAchievementJson()
	{
		if (Achievement_Map == null)
		{
			Achievement_Map = new Dictionary<int, Achievement>();
		}
		Achievement_Map.Clear();
		string text = LoadTableData("json/Achievement.json");
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		table_Achievement table_Achievement2 = table_Achievement.Parser.ParseJson(text);
		if (table_Achievement2 != null)
		{
			int count = table_Achievement2.List.Count;
			for (int i = 0; i < count; i++)
			{
				Achievement achievement = table_Achievement2.List.get_Item(i);
				Achievement_Map.Add(achievement.Id, achievement);
			}
			if (!isLQA)
			{
				HandleAchievementLanguage();
			}
		}
	}

	private void HandleAchievementLanguage()
	{
		Dictionary<string, string> dictionary = LoadLanguageJsonTable("Achievement");
		foreach (KeyValuePair<int, Achievement> achievementDatum in AchievementData)
		{
			string empty = string.Empty;
			empty = achievementDatum.Value.Title;
			if (!string.IsNullOrEmpty(empty))
			{
				if (!dictionary.ContainsKey(empty))
				{
					continue;
				}
				achievementDatum.Value.Title = dictionary.get_Item(empty);
			}
			empty = achievementDatum.Value.Desc;
			if (!string.IsNullOrEmpty(empty) && dictionary.ContainsKey(empty))
			{
				achievementDatum.Value.Desc = dictionary.get_Item(empty);
			}
		}
	}

