	private void LoadAcquireRewardJson()
	{
		if (AcquireReward_Map == null)
		{
			AcquireReward_Map = new Dictionary<int, AcquireReward>();
		}
		AcquireReward_Map.Clear();
		string text = LoadTableData("json/AcquireReward.json");
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		table_AcquireReward table_AcquireReward2 = table_AcquireReward.Parser.ParseJson(text);
		if (table_AcquireReward2 != null)
