	{
		Word_Map = null;
	}

	private void AddWordBin(int key, byte[] data)
	{
		Word word = Word.Parser.ParseFrom(data);
		if (word != null)
		{
			Word_Map.Add(key, word);
		}
	}

	private void LoadWordBin()
	{
		if (Word_Map == null)
		{
			Word_Map = new Dictionary<int, Word>();
		}
		Word_Map.Clear();
		LoadCommonBinData("bin/Word.bytes", AddWordBin, null, null, null);
		if (!isLQA)
		{
			HandleWordLanguage();
		}
	}

	private void LoadWordJson()
	{
		if (Word_Map == null)
		{
			Word_Map = new Dictionary<int, Word>();
		}
		Word_Map.Clear();
		string text = LoadTableData("json/Word.json");
		if (string.IsNullOrEmpty(text))
		{
			return;
		}
		table_Word table_Word2 = table_Word.Parser.ParseJson(text);
		if (table_Word2 != null)
		{
			int count = table_Word2.List.Count;
			for (int i = 0; i < count; i++)
			{
				Word word = table_Word2.List.get_Item(i);
				Word_Map.Add(word.Id, word);
			}
			if (!isLQA)
			{
				HandleWordLanguage();
			}
		}
	}

	private void HandleWordLanguage()
	{
		Dictionary<string, string> dictionary = LoadLanguageJsonTable("Word");
		foreach (KeyValuePair<int, Word> wordDatum in WordData)
		{
			string empty = string.Empty;
			empty = wordDatum.Value.Title;
			if (!string.IsNullOrEmpty(empty))
			{
				if (!dictionary.ContainsKey(empty))
				{
					continue;
				}
				wordDatum.Value.Title = dictionary.get_Item(empty);
			}
			empty = wordDatum.Value.Desc;
			if (!string.IsNullOrEmpty(empty) && dictionary.ContainsKey(empty))
			{
				wordDatum.Value.Desc = dictionary.get_Item(empty);
			}
		}
	}

